import React, { useState } from "react";
import styled from "styled-components";

const TableContainer = styled.div`
  width: 100%;
  background: white;
  padding: 20px;
  border-radius: 8px;
  box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
  margin-top: 30px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow-x: auto;
`;

const Title = styled.h3`
  font-size: 40px;
  font-weight: bold;
  margin-bottom: 30px;
  text-align: center;
`;

const TableWrapper = styled.div`
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
`;

const Table = styled.table`
  width: auto;
  min-width: 100%;
  border-collapse: collapse;
`;

const Th = styled.th`
  background: #d6d6d6;
  color: black;
  padding: 10px;
  text-align: left;
  white-space: nowrap;
`;

const Td = styled.td`
  border: 1px solid #ddd;
  padding: 10px;
  max-width: 150px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: pointer;
  position: relative;

  &:hover::after {
    content: attr(data-tooltip);
    position: absolute;
    background: rgba(0, 0, 0, 0.8);
    color: white;
    padding: 5px;
    border-radius: 4px;
    white-space: normal;
    max-width: 300px;
    left: 50%;
    transform: translateX(-50%);
    bottom: 100%;
    z-index: 10;
  }
`;

const ExpandedTd = styled(Td)`
  white-space: normal;
  overflow: visible;
  text-overflow: initial;
  background: #f9f9f9;
`;

const PlasmidTable = ({ data }) => {
  const [expandedCells, setExpandedCells] = useState({});

  if (!data || data.length === 0) {
    return <p>No data available</p>;
  }

  const rows = data.split("\n").map((row) => row.split("\t"));
  if (rows.length === 0 || rows[0].length === 0) {
    return <p>Invalid data format</p>;
  }

  let headers = [
    "STT",
    "Plasmid ID",
    "Sequence ID",
    "Node Name",
    "Length",
    "Coverage (%)",
    "Identity (%)",
    "Matches",
    "Query Start",
    "Query End",
    "Hit Start",
    "Hit End",
    "E-value"
  ];

  let body = rows.map((row, rowIndex) => [rowIndex + 1, ...row]);

  const toggleExpand = (rowIndex, cellIndex) => {
    setExpandedCells((prev) => ({
      ...prev,
      [`${rowIndex}-${cellIndex}`]: !prev[`${rowIndex}-${cellIndex}`]
    }));
  };

  return (
    <TableContainer>
      <Title>Plasmid Data</Title>
      <TableWrapper>
        <Table>
          <thead>
            <tr>
              {headers.map((header, index) => (
                <Th key={index}>{header}</Th>
              ))}
            </tr>
          </thead>
          <tbody>
            {body.map((row, rowIndex) => (
              <tr key={rowIndex}>
                {row.map((cell, cellIndex) => {
                  const isExpanded = expandedCells[`${rowIndex}-${cellIndex}`];
                  return isExpanded ? (
                    <ExpandedTd
                      key={cellIndex}
                      onClick={() => toggleExpand(rowIndex, cellIndex)}
                    >
                      {cell}
                    </ExpandedTd>
                  ) : (
                    <Td
                      key={cellIndex}
                      data-tooltip={cell}
                      onClick={() => toggleExpand(rowIndex, cellIndex)}
                    >
                      {cell.length > 20 ? `${cell.slice(0, 17)}...` : cell}
                    </Td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </Table>
      </TableWrapper>
    </TableContainer>
  );
};

export default PlasmidTable;
